      const nbrJ = pos[1] + dirJ;
      if (
        nbrI >= 0 &&
        nbrI < room.length &&
        nbrJ >= 0 &&
        nbrJ < room[0].length &&
        room[nbrI][nbrJ] !== 1
      ) {
        moves.push([nbrI, nbrJ]);
      }
