      visit();

      // Undo state changes
      currentPath.pop();
      currentVisited.delete(nextPosStr);
      if (allClues.has(nextPosStr)) {
        currentCluesLeft.add(nextPosStr);
      }
    }
  }

  visit();
  return shortestPath;
}

